PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS AccountUser (id TEXT PRIMARY KEY NOT NULL, username TEXT NOT NULL UNIQUE, passwordHash TEXT NOT NULL, role TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ToyProduct (id TEXT PRIMARY KEY NOT NULL, sku TEXT NOT NULL UNIQUE, category TEXT NOT NULL, ageGroup TEXT NOT NULL, unitPrice DECIMAL NOT NULL, originalPrice DECIMAL, stockCount INTEGER NOT NULL, reorderThreshold INTEGER NOT NULL, storefrontStatus TEXT NOT NULL, productImage TEXT, badge TEXT, name TEXT, subtitle TEXT, description TEXT, longDescription TEXT, highlights JSON NOT NULL, materials TEXT, safetyCertification TEXT, dimensions TEXT, boxIncludes JSON NOT NULL, ratingAverage DECIMAL, reviewsCount INTEGER, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS PromoCode (id TEXT PRIMARY KEY NOT NULL, code TEXT NOT NULL UNIQUE, discountType TEXT NOT NULL, discountValue DECIMAL NOT NULL, minSubtotal DECIMAL, freeShippingThreshold DECIMAL, isActive BOOLEAN NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ShoppingCart (id TEXT PRIMARY KEY NOT NULL, customerId TEXT NOT NULL, cartStatus TEXT NOT NULL, appliedPromoId TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customerId) REFERENCES AccountUser(id), FOREIGN KEY(appliedPromoId) REFERENCES PromoCode(id));
CREATE TABLE IF NOT EXISTS CartItem (id TEXT PRIMARY KEY NOT NULL, cartId TEXT NOT NULL, productId TEXT NOT NULL, quantity INTEGER NOT NULL, customerId TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(cartId) REFERENCES ShoppingCart(id), FOREIGN KEY(productId) REFERENCES ToyProduct(id), FOREIGN KEY(customerId) REFERENCES AccountUser(id));
CREATE TABLE IF NOT EXISTS SalesOrder (id TEXT PRIMARY KEY NOT NULL, customerId TEXT NOT NULL, sourceCartId TEXT NOT NULL, orderStatus TEXT NOT NULL, subtotal DECIMAL NOT NULL, discountAmount DECIMAL NOT NULL, shippingFee DECIMAL NOT NULL, totalAmount DECIMAL NOT NULL, appliedPromoCode TEXT, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customerId) REFERENCES AccountUser(id), FOREIGN KEY(sourceCartId) REFERENCES ShoppingCart(id));
CREATE TABLE IF NOT EXISTS SalesOrderItem (id TEXT PRIMARY KEY NOT NULL, orderId TEXT NOT NULL, productId TEXT NOT NULL, quantity INTEGER NOT NULL, unitPriceSnapshot DECIMAL NOT NULL, lineSubtotal DECIMAL NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(orderId) REFERENCES SalesOrder(id), FOREIGN KEY(productId) REFERENCES ToyProduct(id));
